/**
 * What the ML model did for a planner decision, as text (V0.15 G5b, D373).
 *
 * The TypeScript copy of `src/meshforge/common/ml_explain.py`'s `ml_line` /
 * `ml_decision_text`, the text `compute explain` prints. The two are held
 * identical by the explain-contract fixture's `ml_lines` (generated by the
 * Python functions; `planContract.test.tsx` compares every one) and by the
 * shared `fixed()` table (`mlText.test.ts` = `test_v015_g5b_ml_explain.py`).
 *
 * * used: `ML 2.53 s -> 2.00 s (mem-3a1f00aa, x0.79, +-18 %)`
 * * not used: `ML not used: out of distribution (range:hw_cpu_gflops) (mem-3a1f00aa, x0.82, +-11 %)`
 * * a Mode 3 lane rate (per item) follows as `; rate: ML 110.52 ms/item -> ...`
 */
import type { components } from "../../api/schema";

export type TermMlOut = components["schemas"]["TermMlOut"];
export type TermMlRateOut = components["schemas"]["TermMlRateOut"];

/** `detail.ml.reason` -> words; an unknown reason is shown as it is. */
export const ML_REASON_TEXT: Readonly<Record<string, string>> = {
  no_model: "no model for this term",
  ood: "out of distribution",
  interval_too_wide: "interval too wide",
  exact_by_construction: "exact by construction",
  below_min_predicted: "below the trained range",
  predictor_error: "predictor error",
  combine_node_unknown: "combine node unknown",
};

const MAX_Y_HAT = 50;
const MAX_FIXED = 1e15;
const VERSION_CHARS = 12;

function num(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function text(value: unknown): string | null {
  return typeof value === "string" && value !== "" ? value : null;
}

/** `Number.toFixed` (half away from zero on the exact binary value); "-0.00" -> "0.00"; huge or missing -> "-". */
export function fixed(value: number | null | undefined, digits: number): string {
  if (value == null || !Number.isFinite(value) || Math.abs(value) >= MAX_FIXED) return "-";
  const out = value.toFixed(digits);
  return /^-0(\.0+)?$/.test(out) ? out.slice(1) : out;
}

/** A model set version for a cell: `sha256:` dropped, 12 characters. */
export function shortVersion(version: unknown): string {
  const t = text(version);
  return t === null ? "?" : t.replace(/^sha256:/, "").slice(0, VERSION_CHARS);
}

/** A fallback reason in words. */
export function reasonText(reason: unknown): string {
  const t = text(reason);
  if (t === null) return "?";
  return Object.prototype.hasOwnProperty.call(ML_REASON_TEXT, t) ? (ML_REASON_TEXT[t] ?? t) : t;
}

function factor(yHat: number | null): number | null {
  return yHat === null || Math.abs(yHat) > MAX_Y_HAT ? null : Math.exp(yHat);
}

function said(ml: TermMlRateOut): string {
  const parts = [shortVersion(ml.model_version)];
  const f = factor(num(ml.y_hat));
  if (f !== null) parts.push(`x${fixed(f, 2)}`);
  const lo = num(ml.lo);
  const hi = num(ml.hi);
  if (lo !== null && hi !== null) {
    const spread = (Math.exp(Math.min((hi - lo) / 2, MAX_Y_HAT)) - 1) * 100;
    parts.push(`+-${fixed(spread, 0)} %`);
  }
  return `(${parts.join(", ")})`;
}

function amount(value: unknown, perItem: boolean): string {
  const n = num(value);
  return perItem ? `${fixed(n === null ? null : n * 1000, 2)} ms/item` : `${fixed(n, 2)} s`;
}

function one(ml: TermMlRateOut, perItem: boolean): string {
  if (ml.used) {
    return `ML ${amount(ml.raw_s, perItem)} -> ${amount(ml.corrected_s, perItem)} ${said(ml)}`;
  }
  let why = reasonText(ml.reason);
  const ood = text(ml.ood_reason);
  if (ood !== null) why += ` (${ood})`;
  return `ML not used: ${why} ${said(ml)}`;
}

/** The term's ML line from its typed `ml`; null when there is none. */
export function mlLine(ml: TermMlOut | null | undefined): string | null {
  if (ml == null || typeof ml !== "object") return null;
  let line = one(ml, false);
  if (ml.rate != null && typeof ml.rate === "object") line += `; rate: ${one(ml.rate, true)}`;
  return line;
}

/** The decision's ML part: `ML set <v>` (+ ` - fell back to calibration: predictor error`); null without a model. */
export function mlDecisionText(version: string | null | undefined, fallback: string | null | undefined): string | null {
  if (text(version) === null && text(fallback) === null) return null;
  let out = `ML set ${shortVersion(version)}`;
  if (text(fallback) !== null) out += ` - fell back to calibration: ${reasonText(fallback)}`;
  return out;
}
